const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{JSDOM}=require('jsdom');
const game=path.resolve(__dirname,'../game'),progressApi=require('../game/terrain-progress');let passed=0,failed=0;
async function check(name,fn){try{await fn();passed++;console.log('PASS '+name);}catch(error){failed++;console.error('FAIL '+name+'\n'+error.stack);}}
async function terrain(query='?trial=1',saved={}){return require('./helpers/rescue-ui.cjs').boot('terrain-campaign.html',query,saved);}
(async()=>{
 await check('R1 序章暂停后点击底部漫画不能打开无法返回的档案弹窗',async()=>{const t=await require('./test-campaign-ui.cjs').boot();try{assert(!t.$('prologue').hidden);t.$('prologuePlay').click();const before=t.$('prologueCount').textContent;t.$('footerArchives').click();assert(!t.$('dialog').open,'a paused prologue must keep archive navigation inactive');for(let i=0;i<10;i++)t.frame();assert.equal(t.$('prologueCount').textContent,before);t.$('prologueSkip').click();assert(t.$('dialog').classList.contains('letter-dialog'));}finally{t.d.window.close();}});
 await check('R1 第二章战前从底部打开漫画默认定位当前章节',async()=>{const t=await require('./test-campaign-ui.cjs').boot({saved:{version:2,unlocked:['normal','cone','bucket'],completed:[0,1,2],highest:3,currentLevel:3,prologue:{version:2,status:'completed'}}});try{t.click('收好来信，选择僵尸');t.$('footerArchives').click();assert.equal(t.$('dialogTitle').textContent,t.w.PVZ_STORY.chapters[1].name);t.click('返回菜单');assert(t.$('dialog').classList.contains('menu-dialog'));}finally{t.d.window.close();}});
 await check('R2 开发试演序章不写正式标记，正式冒险收信直接部署且不伪造指南完成',async()=>{const t=await terrain('?trial=1&adventure=1');let formal;try{t.$('replayIntro').click();[...t.w.document.querySelector('.adventure-intro').querySelectorAll('button')].find(b=>b.textContent==='跳过序章').click();t.$('bookClose').click();assert.deepEqual(t.storage(),{});formal=await terrain('?adventure=1',t.storage());assert(formal.w.document.querySelector('.adventure-intro').open);[...formal.w.document.querySelector('.adventure-intro').querySelectorAll('button')].find(b=>b.textContent==='跳过序章').click();formal.$('bookClose').click();assert(!formal.$('storyBook').open);assert.equal(formal.w.localStorage.getItem('pvz-rescue-guide-v1'),null);}finally{formal?.dom.window.close();t.dom.window.close();}});
 await check('R3 无效JSON或非数组旧档不被胜利覆盖，内存内仍可继续下一关',()=>{for(const raw of ['[0,1','{"completed":[0,1]}','null']){let value=raw,writes=0;const p=progressApi.create({getItem:()=>value,setItem:(_k,next)=>{writes++;value=next;}});assert(!p.status().saved);assert.equal(p.complete(0),false);assert.equal(value,raw);assert.equal(writes,0);assert(p.canEnter(1));assert.deepEqual(p.status().completed,[0]);}});
 await check('R3 读取异常不盲写，正常新档/有效旧档以及写失败恢复仍按原进度推进',()=>{let writes=0;const inaccessible=progressApi.create({getItem(){throw Error('unavailable');},setItem(){writes++;}});assert.equal(inaccessible.complete(0),false);assert.equal(writes,0);for(const initial of [null,'[0]']){let value=initial,fail=false;const p=progressApi.create({getItem:()=>value,setItem:(_k,v)=>{if(fail)throw Error('quota');value=v;}});const next=initial?1:0;fail=true;assert(!p.complete(next));assert(p.canEnter(next+1));fail=false;assert(p.complete(next));assert(JSON.parse(value).includes(next));assert(p.status().saved);}});
 await check('R3 坏档在场景短暂告知且胜利不覆盖原文，内存仍可解锁下一关',async()=>{const raw='[0,1',t=await terrain('',{[progressApi.key]:raw});try{t.$('bookClose').click();assert(t.$('feedback').textContent.includes('不会覆盖'));t.s.status='won';t.s.result='terminal fixture';t.tick();assert.equal(t.w.localStorage.getItem(progressApi.key),raw);assert(t.w.PVZ_TERRAIN_PROGRESS.canEnter(1));}finally{t.dom.window.close();}});
 await check('R4 按新界面契约末关停在结算，不再推广设计册或循环首关',async()=>{const t=await terrain('?trial=1&level=39');try{t.$('bookClose').click();t.s.status='won';t.s.result='last-level fixture';t.tick();t.$('bookClose').click();assert(t.$('outcome').open);assert(t.$('next').hidden);assert(t.$('autoRoundBox').hidden);for(let i=0;i<30;i++)t.tick();assert.equal(t.s.levelIndex,39);assert(!t.$('storyBook').open);assert.equal(t.w.localStorage.length,0);}finally{t.dom.window.close();}});
 console.log(JSON.stringify({passed,failed,scope:'confirmed full-review regressions; isolated DOM/production state, not device or full-campaign playthrough'}));if(failed)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
